import{_ as s,o as n,c as e,ai as i}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"内容资产管理","description":"","frontmatter":{},"headers":[],"relativePath":"ai/creation/asset-management.md","filePath":"ai/creation/asset-management.md"}'),l={name:"ai/creation/asset-management.md"};function t(r,a,o,p,c,d){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="内容资产管理" tabindex="-1">内容资产管理 <a class="header-anchor" href="#内容资产管理" aria-label="Permalink to “内容资产管理”">​</a></h1><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>做内容一年后，资产散落的代价开始显现：</p><ul><li>封面图散在下载文件夹，命名全是 <code>image(3).png</code>、<code>未命名-2.jpg</code>，找一张三个月前的封面要翻十分钟；</li><li>发过的文章版本混乱：博客一版、公众号改过一版、后来又更新过一版，不知道哪份是最新的，改错版本白改；</li><li>当时花大钱（时间或 API 费）生成的提示词、分镜表、工作流配置找不到了，同样的东西要重做一遍；</li><li>去年哪篇文章带来了最多的关注、哪类选题数据最好——没有任何记录，复盘全凭印象；</li><li>想复用一篇旧内容，原始素材（图、数据、引用链接）已失效，只能重新收集。</li></ul><p>内容资产和代码一样，<strong>没有归档和版本管理就会持续熵增</strong>。区别是代码有 Git 兜底，内容资产通常什么都没有——直到你被&quot;找不到、改错、重复造&quot;折磨到受不了。</p><h2 id="做法" tabindex="-1">做法 <a class="header-anchor" href="#做法" aria-label="Permalink to “做法”">​</a></h2><h3 id="_1-归档结构-三类资产-一棵目录树" tabindex="-1">1. 归档结构：三类资产，一棵目录树 <a class="header-anchor" href="#_1-归档结构-三类资产-一棵目录树" aria-label="Permalink to “1. 归档结构：三类资产，一棵目录树”">​</a></h3><p>先把资产分三类，各归各位：</p><ul><li><strong>素材（raw）</strong>：生成的图/视频、收集的引用、截图、数据——原料；</li><li><strong>成稿（published）</strong>：各版本文稿、封面终稿、发布链接——成品；</li><li><strong>数据（data）</strong>：各平台发布记录与表现数据——反馈。</li></ul><p>统一目录约定：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>content/</span></span>
<span class="line"><span>├── assets/            # 素材</span></span>
<span class="line"><span>│   ├── images/        # 按项目或主题分</span></span>
<span class="line"><span>│   ├── video-raw/</span></span>
<span class="line"><span>│   └── prompts/       # 提示词、工作流配置（易被忽视但最值钱）</span></span>
<span class="line"><span>├── drafts/            # 生产中的草稿</span></span>
<span class="line"><span>├── published/         # 已发布成稿（按年月或主题）</span></span>
<span class="line"><span>│   └── 2026-10-ai-writing/</span></span>
<span class="line"><span>│       ├── final.md / final.psd</span></span>
<span class="line"><span>│       └── meta.md    # 发布链接、平台、日期</span></span>
<span class="line"><span>└── data/</span></span>
<span class="line"><span>    └── metrics.csv    # 发布数据台账</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>两条规则决定这套结构能不能活：</p><ul><li><strong>单一落点</strong>：一个文件只有一个&quot;正式位置&quot;，临时文件进 <code>_inbox/</code>，每周清一次——混乱都从&quot;先放着&quot;开始；</li><li><strong>命名即元数据</strong>：<code>YYYY-MM-主题-类型-版本</code>（<code>2026-10-ai-writing-cover-v2.png</code>），不靠文件夹层级硬塞所有信息，文件名自己会说话。</li></ul><h3 id="_2-版本管理-成稿用版本后缀-资产清单用-git" tabindex="-1">2. 版本管理：成稿用版本后缀，资产清单用 Git <a class="header-anchor" href="#_2-版本管理-成稿用版本后缀-资产清单用-git" aria-label="Permalink to “2. 版本管理：成稿用版本后缀，资产清单用 Git”">​</a></h3><ul><li><strong>成稿版本</strong>：<code>v1/v2/final</code> 后缀 + 修改日期；改稿前先复制出新版本，不覆盖旧文件——原则和&quot;不改生产库&quot;一样；</li><li><strong>终稿唯一</strong>：<code>final</code> 只有一个，谁是最终版永远明确；发布后如有修订，出 <code>v1.1</code> 并在 meta.md 记一句改了什么；</li><li><strong>meta.md 是每篇内容的&quot;README&quot;</strong>：源文件位置、各平台链接、用过的封面、提示词引用——一篇一个，5 行就够；</li><li><strong>用 Git 管文本资产</strong>：文稿、提示词、分镜表、metrics.csv 这类文本放进一个 Git 仓库，改动历史免费获得；二进制大文件（图/视频）不进 Git，用目录约定 + 元数据清单管理（或用素材管理工具）；</li><li>关键资产（提示词库、模板库）单独成仓，和文章仓库分开，方便跨项目复用。</li></ul><h3 id="_3-可检索-让-找到-变成一次查询" tabindex="-1">3. 可检索：让&quot;找到&quot;变成一次查询 <a class="header-anchor" href="#_3-可检索-让-找到-变成一次查询" aria-label="Permalink to “3. 可检索：让&quot;找到&quot;变成一次查询”">​</a></h3><p>找得到的前提是<strong>每个资产都带可搜索的描述</strong>。三个层级：</p><ul><li><strong>文件名层</strong>：命名规范里强制带主题词（上文的命名即元数据）；</li><li><strong>清单层</strong>：每个项目一个 <code>meta.md</code> / 素材清单，记&quot;这是什么、从哪来、当时什么提示词生成&quot;——生成类素材尤其要记配方（模型、提示词、参数），配方比单张成图更可复用；</li><li><strong>标签层</strong>：给素材打轻量标签（主题、风格、平台、可用状态），标签数量控制在个位数枚举值，标签一多就没人维护了。</li></ul><p>检索习惯：<strong>找东西超过 2 分钟，就停下来补索引</strong>——说明这个资产缺描述或放错了位置，修索引比继续翻划算。AI 的用武之地在这里很明显：把清单丢给它做自然语言查询（&quot;找那张深色系、带传送带意象的封面&quot;），比肉眼翻目录快一个量级。</p><h3 id="_4-复用标记-让旧资产重新上岗" tabindex="-1">4. 复用标记：让旧资产重新上岗 <a class="header-anchor" href="#_4-复用标记-让旧资产重新上岗" aria-label="Permalink to “4. 复用标记：让旧资产重新上岗”">​</a></h3><p>资产的价值在于复用，给关键资产加两个字段：</p><ul><li><strong><code>status</code></strong>：<code>reusable</code>（可直接复用）/ <code>needs-update</code>（数据旧了、需修订）/ <code>retired</code>（作废）；</li><li><strong><code>repurposed</code></strong>：记录这篇/这张被复用到哪里——哪篇长文拆成了哪几条短内容、发在哪些平台、效果如何（与分发台账打通）。</li></ul><p>配合两个触发时机：</p><ul><li><strong>选题会扫一遍 <code>reusable</code></strong>：旧文章更新 30% 就能重发，旧素材直接做新封面，复用是最低成本的产能；</li><li><strong>季度巡检</strong>：过一遍 <code>needs-update</code>，技术类内容时效性强，一篇 2024 年的工具教程要么更新要么标 <code>retired</code>——<strong>过期内容挂着比没有更伤信任</strong>。</li></ul><p>数据资产（metrics.csv）是复用的另一面：每次复盘问&quot;上次类似内容的表现如何&quot;，有台账就有答案，没有就只能靠猜。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>三类资产分树归档：素材/成稿/数据，外加单一落点和 <code>YYYY-MM-主题-类型-版本</code> 命名；</li><li>成稿管版本：不覆盖、final 唯一、meta.md 记链接与修订；文本资产进 Git，配方比成图更值钱；</li><li>可检索三层：文件名 → 项目清单 → 标签，找东西超 2 分钟就补索引，AI 做自然语言查询；</li><li>复用标记 status + repurposed，选题会扫 reusable，季度巡检清过期内容；</li><li>数据台账进归档体系，复盘时&quot;上次怎么样&quot;靠查询不靠印象。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>内容资产管理就是给自己的创作系统装上&quot;版本控制 + 资产索引&quot;：<strong>目录树解决&quot;在哪&quot;，命名和 meta 解决&quot;是什么&quot;，Git 解决&quot;改过什么&quot;，状态标记解决&quot;还能不能用&quot;</strong>。前期多花的每一分纪律，都会在找素材、复用旧文、季度复盘时成倍还回来——这是工程师做内容最不该缺的基础设施。</p>`,29)])])}const h=s(l,[["render",t]]);export{g as __pageData,h as default};
